/**
 * Isolated preview of ONE chapter, with the global background and overlays shifted to the
 * chapter's place in the film, so it looks exactly like it will in "Film". Imports only that
 * chapter's component (never registry.ts), so other chapters' broken files cannot break it.
 * Entry files src/film/preview/<id>.ts are generated by scripts/entry.sh (git-ignored):
 *
 *   registerRoot(makeChapterRoot("C05", C05));   // composition id "C05"
 *   registerRoot(makeChapterRoot("C05"));        // no component yet -> placeholder
 *
 * Duration = the chapter's full length (including its transition overlaps). Plays the
 * chapter's own voice clip. Props: { captions: false } hides the captions (contrast QA).
 */
import React from "react";
import { AbsoluteFill, Audio, Composition, Sequence, staticFile } from "remotion";
import { FPS, HEIGHT, WIDTH } from "../../theme/layout";
import { ChapterId, FILM_START, FILM_TOTAL, chapterFrames, chapterSpec } from "../chapters";
import { VO_TIMING } from "../data/voTiming";
import { Background } from "../overlays/Background";
import { Grain } from "../overlays/Grain";
import { Overlays } from "../overlays/Overlays";
import { placeholderFor } from "../Placeholder";

const Voice: React.FC<{ id: ChapterId }> = ({ id }) => {
  const v = VO_TIMING[id];
  if (!v) return null;
  return (
    <Sequence from={Math.round(v.clipAt * FPS)} layout="none">
      <Audio src={staticFile(v.src)} />
    </Sequence>
  );
};

type PreviewProps = { captions?: boolean };

export const ChapterPreview: React.FC<{ id: ChapterId; Chapter: React.FC } & PreviewProps> = ({
  id,
  Chapter,
  captions = true,
}) => {
  const start = FILM_START[id];
  return (
    <AbsoluteFill>
      <Sequence from={-start} layout="none">
        <Background totalFrames={FILM_TOTAL} />
      </Sequence>
      <Chapter />
      <Sequence from={-start} layout="none">
        <Overlays captions={captions} />
      </Sequence>
      <Grain />
      <Voice id={id} />
    </AbsoluteFill>
  );
};

export const makeChapterRoot = (id: ChapterId, Chapter?: React.FC): React.FC => {
  chapterSpec(id); // throws a readable error for unknown ids
  const Body = Chapter ?? placeholderFor(id);
  const Comp: React.FC<PreviewProps> = ({ captions = true }) => <ChapterPreview id={id} Chapter={Body} captions={captions} />;
  return () => (
    <Composition
      id={id}
      component={Comp}
      durationInFrames={chapterFrames(id)}
      fps={FPS}
      width={WIDTH}
      height={HEIGHT}
      defaultProps={{ captions: true }}
    />
  );
};
